?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login — OTPGenerator</title><style>body{margin:0;background:#f6f7fb;font-family:system-ui;color:#151827}.box{max-width:420px;margin:10vh auto;background:#fff;padding:30px;border-radius:18px;border:1px solid #e5e6ee}input{width:100%;box-sizing:border-box;padding:13px;margin:7px 0 15px;border:1px solid #ddd;border-radius:9px}button{background:#6d35e8;color:white;border:0;padding:13px 18px;border-radius:9px;font-weight:700;width:100%}.err{color:#b42318;margin:10px 0}</style></head><body><div class="box"><h1>OTPGenerator</h1><p>Sign in to your verification dashboard.</p><div id="err" class="err"></div><form id="f"><label>Email</label><input name="email" type="email" required><label>Password</label><input name="password" type="password" required><button>Sign in</button></form><p><a href="app.php">Create an account</a></p></div><script>f.onsubmit=async e=>{e.preventDefault();let r=await fetch('index.php?route=login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(f)))});let j=await r.json();if(j.success)location='dashboard.php';else err.textContent=j.message}</script></body></html>
